window.ARB_DOCS["choice_sets"]={"reasons_bankrot_gr":{"label":"Основание признания гражданина банкротом","options":[{"value":"plan_requirements","label":"Не соответствует требованиям для утверждения плана","text":"гражданин не соответствует требованиям для утверждения плана реструктуризации долгов (п. 1 ст. 213.13, п. 8 ст. 213.6 127-ФЗ)","norm":"п. 1 ст. 213.13, п. 8 ст. 213.6 127-ФЗ"},{"value":"income_insufficient","label":"Дохода недостаточно для погашения в пределах трёх лет","text":"дохода гражданина недостаточно для погашения требований кредиторов в срок, не превышающий трёх лет (п. 2 ст. 213.14 127-ФЗ)","norm":"п. 2 ст. 213.14 127-ФЗ"},{"value":"plan_not_submitted","label":"План не представлен в срок","text":"план реструктуризации долгов не представлен в установленный срок (п. 1 ст. 213.24 127-ФЗ)","norm":"п. 1 ст. 213.24 127-ФЗ"},{"value":"meeting_rejected","label":"Собрание не одобрило план / решило обратиться в суд","text":"собрание кредиторов {{ДАТА_СОБРАНИЯ}} не одобрило план реструктуризации долгов и приняло решение обратиться в арбитражный суд с ходатайством о признании гражданина банкротом (п. 1 ст. 213.24, ст. 213.17 127-ФЗ)","norm":"п. 1 ст. 213.24, ст. 213.17 127-ФЗ","fields":["ДАТА_СОБРАНИЯ"]},{"value":"plan_cancelled","label":"План отменён","text":"план реструктуризации долгов отменён арбитражным судом (п. 1 ст. 213.24, ст. 213.23 127-ФЗ)","norm":"п. 1 ст. 213.24, ст. 213.23 127-ФЗ"},{"value":"debtor_petition","label":"Ходатайство гражданина","text":"гражданин ходатайствует о признании его банкротом и введении процедуры реализации имущества (п. 1 ст. 213.24, п. 8 ст. 213.6 127-ФЗ)","norm":"п. 1 ст. 213.24, п. 8 ст. 213.6 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"reasons_bankrot_gr","allow_custom":true},"grounds_zavershenie_gr":{"label":"Основание завершения реализации имущества","options":[{"value":"completed","label":"Мероприятия выполнены, имущество реализовано","text":"все мероприятия процедуры реализации имущества выполнены, выявленное имущество реализовано, вырученные средства распределены между кредиторами","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"no_estate","label":"Конкурсной массы нет","text":"конкурсная масса не сформирована: имущество, подлежащее реализации, не выявлено, дальнейшее проведение мероприятий не приведёт к поступлению средств","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"fully_paid","label":"Требования погашены полностью","text":"требования кредиторов, включённые в реестр, погашены в полном объёме","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"grounds_zavershenie_gr","allow_custom":true},"discharge_gr":{"label":"Освобождение от обязательств","default":"apply","options":[{"value":"apply","label":"Применить освобождение (по умолчанию)","text":"Применить в отношении гражданина правила об освобождении от исполнения обязательств (п. 3 ст. 213.28 127-ФЗ); обстоятельства, предусмотренные п. 4 ст. 213.28 127-ФЗ, не выявлены","norm":"п. 3, 4 ст. 213.28 127-ФЗ","default":true},{"value":"deny_illegal","label":"Не применять: незаконные действия при возникновении или исполнении обязательства","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: при возникновении или исполнении обязательства гражданин действовал незаконно (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_info","label":"Не применять: непредоставление или искажение сведений","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин не предоставил необходимые сведения или предоставил заведомо недостоверные сведения финансовому управляющему или арбитражному суду (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_concealment","label":"Не применять: сокрытие или уничтожение имущества","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин скрыл или умышленно уничтожил имущество (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_liability","label":"Не применять: привлечение к ответственности, преднамеренное или фиктивное банкротство","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин привлечён к уголовной или административной ответственности за неправомерные действия при банкротстве, преднамеренное или фиктивное банкротство (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"discharge_gr","allow_custom":true},"conclusion_prednamerennoe":{"label":"Вывод о признаках преднамеренного банкротства","prefill_from":"finanalysis","options":[{"value":"found","label":"выявлены","text":"признаки преднамеренного банкротства выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"not_found","label":"не выявлены","text":"признаки преднамеренного банкротства не выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_prednamerennoe","allow_custom":true},"conclusion_fiktivnoe":{"label":"Вывод о признаках фиктивного банкротства","prefill_from":"finanalysis","options":[{"value":"found","label":"выявлены","text":"признаки фиктивного банкротства выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"not_found","label":"не выявлены","text":"признаки фиктивного банкротства не выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_fiktivnoe","allow_custom":true},"conclusion_sdelki":{"label":"Вывод об основаниях для оспаривания сделок","prefill_from":"finanalysis","options":[{"value":"exist","label":"есть","text":"выявлены сделки, имеющие признаки недействительности по ст. 61.2, 61.3 127-ФЗ; основания для их оспаривания имеются","norm":"ст. 61.2, 61.3 127-ФЗ"},{"value":"absent","label":"отсутствуют","text":"основания для оспаривания сделок должника по ст. 61.2, 61.3 127-ФЗ отсутствуют","norm":"ст. 61.2, 61.3 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_sdelki","allow_custom":true},"conclusion_sufficiency":{"label":"Вывод о достаточности имущества","prefill_from":"finanalysis","options":[{"value":"sufficient","label":"достаточно","text":"имущества должника достаточно для покрытия судебных расходов и расходов на выплату вознаграждения арбитражному управляющему","norm":"ст. 20.6, 59 127-ФЗ; Правила проведения арбитражным управляющим финансового анализа, утв. постановлением Правительства РФ от 25.06.2003 № 367"},{"value":"insufficient","label":"недостаточно","text":"имущества должника недостаточно для покрытия судебных расходов и расходов на выплату вознаграждения арбитражному управляющему","norm":"ст. 20.6, 59 127-ФЗ; Правила проведения арбитражным управляющим финансового анализа, утв. постановлением Правительства РФ от 25.06.2003 № 367"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_sufficiency","allow_custom":true},"control_grounds_6110":{"label":"Основание отнесения ответчика к КДЛ","multiple":true,"source":"documents/control_grounds.json (Судебная практика)","edition_checked":"Гарант, действующая редакция на 16.10.2026; ПП ВС № 53 — с изм. ПП ВС от 23.12.2025 № 42","options":[{"value":"p2_1_rodstvo","label":"Родство/свойство с руководством или должностное положение","text":"ответчик имел возможность определять действия должника в силу нахождения с должником (руководителем или членами органов управления должника) в отношениях родства или свойства либо в силу должностного положения (пп. 1 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 1 п. 2 ст. 61.10 127-ФЗ","quote":"1) в силу нахождения с должником (руководителем или членами органов управления должника) в отношениях родства или свойства, должностного положения;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_2_doverennost","label":"Полномочия на сделки по доверенности или спецполномочию","text":"ответчик имел возможность определять действия должника в силу наличия полномочий совершать сделки от имени должника, основанных на доверенности, нормативном правовом акте либо ином специальном полномочии (пп. 2 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 2 п. 2 ст. 61.10 127-ФЗ","quote":"2) в силу наличия полномочий совершать сделки от имени должника, основанных на доверенности, нормативном правовом акте либо ином специальном полномочии;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_3_dolzhnost","label":"Должность: главбух, финдиректор и т.п.","text":"ответчик имел возможность определять действия должника в силу должностного положения (замещал должность главного бухгалтера, финансового директора должника либо иную должность, предоставляющую возможность определять действия должника) (пп. 3 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 3 п. 2 ст. 61.10 127-ФЗ","quote":"3) в силу должностного положения (в частности, замещения должности главного бухгалтера, финансового директора должника либо лиц, указанных в подпункте 2 пункта 4 настоящей статьи, а также иной должности, предоставляющей возможность определять действия должника);","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_4_inoe_vliyanie","label":"Принуждение или определяющее влияние на руководство","text":"ответчик имел возможность определять действия должника иным образом, в том числе путём принуждения руководителя или членов органов управления должника либо оказания на них определяющего влияния (пп. 4 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 4 п. 2 ст. 61.10 127-ФЗ","quote":"4) иным образом, в том числе путем принуждения руководителя или членов органов управления должника либо оказания определяющего влияния на руководителя или членов органов управления должника иным образом.","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p4_1_rukovoditel","label":"Презумпция: руководитель, член исп. органа, ликвидатор","text":"ответчик являлся руководителем должника (управляющей организации должника, членом исполнительного органа должника, ликвидатором должника, членом ликвидационной комиссии) и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 1 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 1 п. 4 ст. 61.10 127-ФЗ","quote":"Пока не доказано иное, предполагается, что лицо являлось контролирующим должника лицом, если это лицо: 1) являлось руководителем должника или управляющей организации должника, членом исполнительного органа должника, ликвидатором должника, членом ликвидационной комиссии;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"p4_2_uchastnik","label":"Презумпция: ≥50% акций, >½ долей или назначение руководителя","text":"ответчик имел право самостоятельно либо совместно с заинтересованными лицами распоряжаться пятьюдесятью и более процентами голосующих акций (более чем половиной долей уставного капитала, более чем половиной голосов в общем собрании участников) либо право назначать (избирать) руководителя должника и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 2 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 2 п. 4 ст. 61.10 127-ФЗ","quote":"2) имело право самостоятельно либо совместно с заинтересованными лицами распоряжаться пятьюдесятью и более процентами голосующих акций акционерного общества, или более чем половиной долей уставного капитала общества с ограниченной (дополнительной) ответственностью, или более чем половиной голосов в общем собрании участников юридического лица либо имело право назначать (избирать) руководителя должника;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"p4_3_vygoda","label":"Презумпция: выгода от недобросовестного поведения органов","text":"ответчик извлекал выгоду из незаконного или недобросовестного поведения лиц, указанных в п. 1 ст. 53.1 ГК РФ, и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 3 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 3 п. 4 ст. 61.10 127-ФЗ","quote":"3) извлекало выгоду из незаконного или недобросовестного поведения лиц, указанных в пункте 1 статьи 53.1 Гражданского кодекса Российской Федерации.","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"custom","label":"Свой вариант","text":"","norm":"","quote":"","source_url":"","group":""}],"id":"control_grounds_6110","allow_custom":true},"liability_grounds":{"label":"Основание ответственности КДЛ","multiple":true,"source":"documents/liability_grounds.json (Судебная практика)","edition_checked":"Гарант, действующая редакция на 16.10.2026; ПП ВС № 53 — с изм. ПП ВС от 23.12.2025 № 42","options":[{"value":"p61_11_1","label":"Невозможность погашения из-за действий (бездействия) КДЛ","text":"полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия ответчика как контролирующего должника лица (п. 1 ст. 61.11 Закона о банкротстве)","norm":"п. 1 ст. 61.11 127-ФЗ","quote":"Если полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия контролирующего должника лица, такое лицо несет субсидиарную ответственность по обязательствам должника.","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения"},{"value":"p61_11_2_1","label":"Презумпция: сделки, причинившие существенный вред","text":"кредиторам причинён существенный вред в результате совершения ответчиком или в его пользу либо одобрения им сделок должника (совершения сделок по его указанию), включая сделки по ст. 61.2 и 61.3 Закона о банкротстве; невозможность полного погашения требований презюмируется (пп. 1 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 1 п. 2 ст. 61.11 127-ФЗ","quote":"Пока не доказано иное, предполагается, что полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия контролирующего должника лица при наличии хотя бы одного из следующих обстоятельств: 1) причинен существенный вред имущественным правам кредиторов в результате совершения этим лицом или в пользу этого лица либо одобрения этим лицом одной или нескольких сделок должника (совершения таких сделок по указанию этого лица), включая сделки, указанные в статьях 61.2 и 61.3 настоящего Федерального закона;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_11_2_2","label":"Презумпция: нет или искажены документы бухучёта","text":"документы бухгалтерского учёта и (или) отчётности к моменту введения наблюдения (признания должника банкротом) отсутствуют, не содержат обязательной информации либо она искажена, в результате чего существенно затруднено проведение процедур банкротства, в том числе формирование и реализация конкурсной массы (пп. 2 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 2 п. 2 ст. 61.11 127-ФЗ","quote":"2) документы бухгалтерского учета и (или) отчетности, обязанность по ведению (составлению) и хранению которых установлена законодательством Российской Федерации, к моменту вынесения определения о введении наблюдения (либо ко дню назначения временной администрации финансовой организации) или принятия решения о признании должника банкротом отсутствуют или не содержат информацию об объектах, предусмотренных законодательством Российской Федерации, формирование которой является обязательным в соответствии с законодательством Российской Федерации, либо указанная информация искажена, в результате чего существенно затруднено проведение процедур, применяемых в деле о банкротстве, в том числе формирование и реализация конкурсной массы;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","valid_until":"2027-07-26","valid_until_note":"подпункт изменён с 27.07.2027 Федеральным законом от 26.07.2026 № 253-ФЗ; будущая редакция не сверялась — вариант дан по действующей","parent":"p61_11_1"},{"value":"p61_11_2_3","label":"Презумпция: >50% реестра 3-й очереди — из правонарушений","text":"требования кредиторов третьей очереди по основной сумме задолженности, возникшие вследствие правонарушения, за которое должник или его единоличный исполнительный орган привлечён к уголовной, административной или налоговой ответственности, превышают 50% общего размера требований третьей очереди по основной сумме долга, включённых в реестр (пп. 3 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 3 п. 2 ст. 61.11 127-ФЗ","quote":"3) требования кредиторов третьей очереди по основной сумме задолженности, возникшие вследствие правонарушения, за совершение которого вступило в силу решение о привлечении должника или его должностных лиц, являющихся либо являвшихся его единоличными исполнительными органами, к уголовной, административной ответственности или ответственности за налоговые правонарушения, в том числе требования об уплате задолженности, выявленной в результате производства по делам о таких правонарушениях, превышают пятьдесят процентов общего размера требований кредиторов третьей очереди по основной сумме задолженности, включенных в реестр требований кредиторов;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_11_2_4","label":"Презумпция: нет или искажены корпоративные документы","text":"документы, хранение которых являлось обязательным по законодательству об АО, о рынке ценных бумаг, об инвестиционных фондах, об ООО, о ГУП и МУП, к моменту введения наблюдения (признания должника банкротом) отсутствуют либо искажены (пп. 4 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 4 п. 2 ст. 61.11 127-ФЗ","quote":"4) документы, хранение которых являлось обязательным в соответствии с законодательством Российской Федерации об акционерных обществах, о рынке ценных бумаг, об инвестиционных фондах, об обществах с ограниченной ответственностью, о государственных и муниципальных унитарных предприятиях и принятыми в соответствии с ним нормативными правовыми актами, к моменту вынесения определения о введении наблюдения (либо ко дню назначения временной администрации финансовой организации) или принятия решения о признании должника банкротом отсутствуют либо искажены;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","valid_until":"2027-07-26","valid_until_note":"подпункт изменён с 27.07.2027 Федеральным законом от 26.07.2026 № 253-ФЗ; будущая редакция не сверялась — вариант дан по действующей","parent":"p61_11_1"},{"value":"p61_11_2_5","label":"Презумпция: нет или недостоверны сведения в ЕГРЮЛ/ЕФРСДЮЛ","text":"на дату возбуждения дела о банкротстве не внесены обязательные сведения либо внесены недостоверные сведения о должнике в ЕГРЮЛ и (или) в Единый федеральный реестр сведений о фактах деятельности юридических лиц (пп. 5 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 5 п. 2 ст. 61.11 127-ФЗ","quote":"5) на дату возбуждения дела о банкротстве не внесены подлежащие обязательному внесению в соответствии с федеральным законом сведения либо внесены недостоверные сведения о юридическом лице: в единый государственный реестр юридических лиц на основании представленных таким юридическим лицом документов; в Единый федеральный реестр сведений о фактах деятельности юридических лиц в части сведений, обязанность по внесению которых возложена на юридическое лицо.","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_12","label":"Неподача (несвоевременная подача) заявления должника","text":"ответчик не исполнил обязанность по подаче заявления должника в арбитражный суд (созыву заседания или принятию решения об обращении) в случаях и в срок, установленные ст. 9 Закона о банкротстве; размер ответственности равен размеру обязательств должника, возникших после истечения срока по п. 2–4 ст. 9 и до возбуждения дела о банкротстве (п. 1, 2 ст. 61.12 Закона о банкротстве)","norm":"п. 1, 2 ст. 61.12 127-ФЗ","quote":"Неисполнение обязанности по подаче заявления должника в арбитражный суд (созыву заседания для принятия решения об обращении в арбитражный суд с заявлением должника или принятию такого решения) в случаях и в срок, которые установлены статьей 9 настоящего Федерального закона, влечет за собой субсидиарную ответственность лиц … Размер ответственности в соответствии с настоящим пунктом равен размеру обязательств должника (в том числе по обязательным платежам), возникших после истечения срока, предусмотренного пунктами 2 - 4 статьи 9 настоящего Федерального закона, и до возбуждения дела о банкротстве должника (возврата заявления уполномоченного органа о признания должника банкротом).","source_url":"https://base.garant.ru/185181/0d0ea8cc116ee92c002c9bfac3919095/","group":"ст. 61.12 — неподача заявления должника"},{"value":"custom","label":"Свой вариант","text":"","norm":"","quote":"","source_url":"","group":""}],"excluded_options":[{"value":"p61_13_ubytki","label":"Убытки от нарушения Закона о банкротстве","norm":"п. 1 ст. 61.13 127-ФЗ","link_template":"zayavlenie_ubytki","reason":"убытки по ст. 61.13 — отдельное требование (размер — доказанные убытки, не реестр); оформляется шаблоном zayavlenie_ubytki"}],"id":"liability_grounds","allow_custom":true},"poshlina_mode":{"label":"Государственная пошлина","options":[{"value":"paid","label":"Уплачена","text":"Уплачена, платёжное поручение прилагается","norm":"пп. 9 п. 1 ст. 333.21 НК РФ; п. 2 ч. 1 ст. 126 АПК РФ"},{"value":"deferral","label":"Отсрочка","text":"Заявлено ходатайство об отсрочке (ст. 333.41 НК)","norm":"ст. 333.41 НК РФ; ст. 102 АПК РФ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"poshlina_mode","allow_custom":true}};
