window.ARB_DOCS["computed_meta"]={"source":"computed_deadlines.json / computed_deadlines.md v1.1 (Судебная практика, 2026-10-16); числа, нормы и типы дней — только оттуда","placement":"templates[i].computed[ПОЛЕ] — блок расчёта на уровне шаблона (одно поле в разных шаблонах может считаться по-разному); computed[ПОЛЕ] = null — срока по закону нет (no_statutory_term), причина в templates[i].computed_null_reason[ПОЛЕ]","direction":{"not_after":"поле ≤ from + offset (крайний срок)","not_before":"поле ≥ from + offset (минимальная дата)","exact":"поле = from + offset (значение по умолчанию)"},"units":{"calendar_days":"календарные дни","working_days":"рабочие дни (производственный календарь)","months":"месяцы","years":"годы","chain":"цепочка сдвигов: offset — список {offset, unit}, применяется по порядку","by_procedure":"текстовое значение по процедуре (variants)","by_property_type":"текстовое значение по виду имущества (variants)"},"shift_rules":[{"case":"«не позднее N с даты» (direction=not_after, offset > 0)","shift":"next_working_day","norm":"ст. 193 ГК РФ","verified":true},{"case":"«не позднее чем за N до события» (direction=not_after, offset < 0)","shift":"previous_working_day","norm":"вывод из ст. 193 ГК РФ (прямой нормы нет)","verified":true},{"case":"«не ранее» (direction=not_before)","shift":"next_working_day","norm":"перенос вперёд срок не нарушает","verified":true},{"case":"exact (значение по умолчанию)","shift":"none","norm":"правило Arbitr: значение предлагается без сдвига, пользователь может изменить","verified":true},{"case":"месяцы и годы","shift":"соответствующее число последнего месяца (года); если такого числа нет — последний день месяца","norm":"п. 1, 3 ст. 192 ГК РФ","verified":true},{"case":"«дней» без уточнения","shift":"календарные дни; рабочие дни закон называет прямо","norm":"толкование по тексту 127-ФЗ","verified":true},{"case":"начало течения срока","shift":"со следующего дня после события","norm":"ст. 191 ГК РФ","verified":true},{"case":"трудовые сроки (ТК РФ)","shift":"начало — со следующего дня; окончание в нерабочий день переносится на следующий рабочий","norm":"ст. 14 ТК РФ","verified":true}],"calculation_rules_source":[{"rule":"Перенос с нерабочего дня на следующий рабочий применяется только к концу срока «не позднее» (direction=not_after при положительном offset)","norm":"ст. 193 ГК РФ","quote":"Если последний день срока приходится на нерабочий день, днем окончания срока считается ближайший следующий за ним рабочий день.","source_url":"https://base.garant.ru/10164072/9ab581f332f422774f6e67652ce80a1c/","source_url_alt":"https://zakonrf.info/gk/193/"},{"rule":"Для сроков «не позднее чем за N дней ДО события» (offset<0, not_after) перенос вперёд нарушает срок: с нерабочего дня сдвигать НАЗАД","norm":"вывод из ст. 193 ГК (прямой нормы нет)"},{"rule":"Для «не ранее» (not_before) перенос вперёд срок не нарушает, можно предлагать ближайший рабочий день","norm":"—"},{"rule":"Месяцы и годы — соответствующее число; если такого числа нет — последний день месяца","norm":"п. 1, 3 ст. 192 ГК РФ","quote":"Срок, исчисляемый годами, истекает в соответствующие месяц и число последнего года срока. | Срок, исчисляемый месяцами, истекает в соответствующее число последнего месяца срока. … Если окончание срока, исчисляемого месяцами, приходится на такой месяц, в котором нет соответствующего числа, то срок истекает в последний день этого месяца.","source_url":"https://base.garant.ru/10164072/eee2dfc53c633b2005c2409be06a1d1e/","source_url_alt":"https://zakonrf.info/gk/192/"},{"rule":"«дней» без уточнения = календарные дни; рабочие дни закон всегда называет прямо («рабочих дней»)","norm":"толкование по тексту 127-ФЗ"},{"rule":"Начало срока — на следующий день после события (ст. 191 ГК)","norm":"ст. 191 ГК РФ","quote":"Течение срока, определенного периодом времени, начинается на следующий день после календарной даты или наступления события, которыми определено его начало.","source_url":"https://base.garant.ru/10164072/c310495fb04e03cd147b58ba5fee6e32/"},{"rule":"ТК: сроки прекращения трудовых прав начинаются на следующий день; в календарные дни включаются нерабочие; окончание в нерабочий день переносится на следующий рабочий","norm":"ст. 14 ТК РФ","quote":"Если последний день срока приходится на нерабочий день, то днем окончания срока считается ближайший следующий за ним рабочий день.","source_url":"https://base.garant.ru/12125268/888134b28b1397ffae87a0ab1e117954/"},{"rule":"Десятидневный срок п. 1 ст. 213.12 считается по правилам гл. 11 ГК","norm":"п. 27 ПП ВС № 45","quote":"27. В процедуре реструктуризации долгов должник, его кредиторы или уполномоченный орган не позднее чем в течение десяти дней со дня истечения срока, предусмотренного пунктом 2 статьи 213.8 Закона о банкротстве, вправе направить финансовому управляющему, конкурсным кредиторам, в уполномоченный орган проект плана реструктуризации долгов (пункт 1 статьи 213.12 Закона о банкротстве). Указанный десятидневный срок исчисляется по правилам главы 11 ГК РФ.","source_url":"https://base.garant.ru/71217118/"}],"future_changes":{"note":"Гарант отмечает уже принятые, но не вступившие изменения в используемых нормах. Расчёты сделаны по редакции на 16.10.2026.","items":["253-ФЗ от 26.07.2026, с 27.07.2027: меняются ст. 9 (п. 1–3), 12 (п. 1, 2), 15 (п. 2), 20.3 (п. 2), 24.1 (п. 2), 28 (п. 6–6.7, 8), 61.2 (п. 1, 2), 61.3 (п. 2, 3), 61.9 (п. 1), 75, 110 (п. 6, 16, 18), 126 (п. 2, плюс новые п. 5–10), 129 (п. 2, 6), 130 (п. 3, 4), 139 (п. 1, 5), 213.7; ст. 70 утрачивает силу; добавляется глава III.3","253-ФЗ: ст. 139 п. 3 — с 01.01.2028; ст. 213.9 п. 2 и ст. 24.1 п. 2.1 — с 30.03.2030","230-ФЗ от 04.07.2026, с 01.01.2027: ст. 213.24 п. 5, ст. 213.25 п. 8","Тексты будущих редакций не читал. Нормы, затронутые 253-ФЗ, нужно пересчитать до 27.07.2027: 126 п. 2 (3 дня), 129 п. 2 (3 месяца, 3 рабочих дня, 1 месяц), 61.2 (периоды), 139 п. 1, 110 п. 16."]},"keys":{"from":"поле-основание расчёта (null — основания-поля нет, см. from_note)","from_note":"исходная формулировка from из файла Судебной практики, если она не имя поля","from_fields":"несколько полей-оснований","from_mode":"first_filled — первое заполненное по порядку; max_all_required — наибольшая из дат, считается только если заполнены все","offset":"величина сдвига (отрицательная — «за N до»)","unit":"единица (см. units)","direction":"not_after / not_before / exact (см. direction)","norm":"норма","quote":"цитата нормы","source_url":"источник текста нормы","note":"пояснение Судебной практики","variants":"варианты по условию / процедуре / виду имущества","condition":"условие применения","requires_new_field":"пометка Судебной практики о новом поле","hint_only":"только подсказка, дату не подставлять","extra":"дополнительные проверки","quote_condition":"цитата к условию","result":"date — рассчитывается дата; text — подставляется текст срока по варианту","conditional_block":"блок действует только при включённом условном блоке шаблона","verified":"false — в файле Судебной практики пометка «проверить» / норма не прочитана; нужна сверка Юридическим консультантом"}};
